"""Rebuild figures using participant-bootstrap intervals generated by reproduce.py."""
from pathlib import Path
import os
import tempfile
os.environ.setdefault('MPLCONFIGDIR',str(Path(tempfile.gettempdir())/'trace-matplotlib'))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from reproduce import ROOT, CONDITIONS, LABELS, OUTCOMES, SURVEY

COLORS = ['#65758B','#D28B2D','#087F8C']
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,
                     'axes.spines.right':False,'axes.titleweight':'bold','svg.fonttype':'none'})


def export(fig,name):
    target=ROOT/'figures'; target.mkdir(exist_ok=True)
    for ext in ['pdf','svg','png']:
        metadata = {'Creator':'','Date':None} if ext=='svg' else ({'Creator':'','Producer':'','CreationDate':None,'ModDate':None} if ext=='pdf' else {'Software':'TRACE supplement'})
        fig.savefig(target/f'{name}.{ext}',dpi=300,bbox_inches='tight',metadata=metadata)
    plt.close(fig)


def main():
    data=pd.read_csv(ROOT/'results/task_descriptives.csv')
    fig,axes=plt.subplots(3,3,figsize=(11.5,10.5))
    for ax,(outcome,(label,lo,hi)) in zip(axes.flat,OUTCOMES.items()):
        rows=data[data.outcome==outcome].set_index('condition').loc[CONDITIONS]
        means=rows['mean'].to_numpy()
        err=np.stack([means-rows.mean_ci_low,rows.mean_ci_high-means])
        ax.bar(range(3),means,color=COLORS,width=.64)
        ax.errorbar(range(3),means,yerr=err,fmt='none',ecolor='#172435',capsize=4,lw=1.2)
        ax.set_xticks(range(3),[LABELS[c] for c in CONDITIONS],fontsize=8)
        ax.set_title(label,fontsize=11,pad=12)
        ax.set_ylim(0, hi*1.14 if hi is not None else 1.6)
        ax.set_axisbelow(True);ax.yaxis.grid(alpha=.15)
        for i,v in enumerate(means): ax.text(i,rows.iloc[i].mean_ci_high+.03, f'{v:.2f}',ha='center',fontsize=9)
    fig.suptitle('Task outcomes by condition',fontsize=18,x=.08,ha='left')
    fig.text(.08,.03,'35 participants; 95% percentile intervals from 20,000 participant bootstrap resamples.\nLower calibration error and lower annoyance are preferable.',fontsize=10)
    fig.tight_layout(rect=(.03,.07,1,.94));export(fig,'figure_2_recomputed')
    survey=pd.read_csv(ROOT/'results/table_3.csv',dtype={'p_holm_reported':str})
    fig,ax=plt.subplots(figsize=(10,5.8))
    ypos=np.arange(len(survey))[::-1]
    for i,row in survey.iterrows():
        y=ypos[i]
        ax.plot([row.Generic,row.Personalized],[y,y],c='#BCC5CF',lw=3,zorder=1)
        for value,color,marker,offset in [(row.Generic,COLORS[1],'o',.17),(row.Personalized,COLORS[2],'D',-.23)]:
            ax.scatter(value,y,c=color,s=70,marker=marker,zorder=2)
            ax.text(value,y+offset,f'{value:.2f}',ha='center',fontsize=10)
        ax.text(5.2,y,row.p_holm_reported,va='center',fontsize=11)
    ax.set_yticks(ypos,survey.item);ax.set_ylim(-.6,5.65);ax.set_xlim(.9,5.7)
    ax.set_xticks(range(1,6));ax.set_xlabel('Mean rating (1–5)')
    ax.text(5.2,5.5,'p_H',va='center',fontsize=12)
    ax.spines[['left','right','top']].set_visible(False);ax.tick_params(axis='y',length=0)
    ax.xaxis.grid(alpha=.15);ax.set_axisbelow(True)
    from matplotlib.lines import Line2D
    ax.legend(handles=[Line2D([],[],color=COLORS[1],marker='o',ls='',label='Generic'),
                       Line2D([],[],color=COLORS[2],marker='D',ls='',label='Personalized')],
              loc='upper center',bbox_to_anchor=(.5,1.16),ncol=2,frameon=False)
    fig.text(.03,.02,'Manuscript Figure 3 values; paired Wilcoxon tests with Holm adjustment. Lower annoyance is preferable.',fontsize=9)
    fig.tight_layout(rect=(0,.06,1,.97));export(fig,'figure_3_reported')
    print('Wrote task and manuscript survey figures in PDF, SVG, and 300 dpi PNG.')


if __name__=='__main__':main()
